46	/** Converts a DocsIndexEntry to a DocsManifestEntry by reading its file content. */
47	export async function createDocsManifestEntry(entry: DocsIndexEntry): Promise<DocsManifestEntry> {
48	  const absolutePath = path.join(process.cwd(), entry.importPath);
49	  try {
50	    const content = await fs.readFile(absolutePath, 'utf-8');
51	
52	    /*
53	      TODO: This isn't the most performant option, as we're already analyzing the MDX file
54	      during story index generation, and analyzing it requires compiling the file.
55	      We should find a way to only do it once and cache/access the analysis somehow
56	    */
57	    const { summary } = await analyzeMdx(content);
58	
59	    return {
60	      id: entry.id,
61	      name: entry.name,
62	      path: entry.importPath,
63	      title: entry.title,
64	      content,
65	      ...(summary && { summary }),
66	    };
67	  } catch (err) {
68	    return {
69	      id: entry.id,
70	      name: entry.name,
71	      path: entry.importPath,
72	      title: entry.title,
73	      error: {
74	        name: err instanceof Error ? err.name : 'Error',
75	        message: err instanceof Error ? err.message : String(err),
76	      },
77	    };
78	  }
79	}
