81	/**
82	 * Extracts unattached MDX entries (standalone docs not attached to any component). These are added
83	 * to a separate `docs` manifest.
84	 */
85	export async function extractUnattachedDocsEntries(
86	  entries: DocsIndexEntry[]
87	): Promise<Record<string, DocsManifestEntry>> {
88	  if (entries.length === 0) {
89	    return {};
90	  }
91	  const entriesWithContent = await Promise.all(entries.map(createDocsManifestEntry));
92	  return Object.fromEntries(entriesWithContent.map((entry) => [entry.id, entry]));
93	}
