95	/**
96	 * Extracts attached docs entries by adding them to their corresponding component manifests.
97	 *
98	 * Returns the updated components manifest with docs added to each component.
99	 */
100	export async function extractAttachedDocsEntries(
101	  entries: DocsIndexEntry[],
102	  existingComponents: ComponentsManifestWithDocs | undefined
103	): Promise<ComponentsManifestWithDocs | undefined> {
104	  if (!existingComponents || entries.length === 0) {
105	    return existingComponents;
106	  }
107	
108	  const entriesWithContent = await Promise.all(entries.map(createDocsManifestEntry));
109	
110	  // Add docs to their corresponding components based on the entry id prefix
111	  for (const docsEntry of entriesWithContent) {
112	    const componentId = docsEntry.id.split('--')[0];
113	
114	    const component = existingComponents.components[componentId];
115	    if (component) {
116	      if (!component.docs) {
117	        component.docs = {};
118	      }
119	      component.docs[docsEntry.id] = docsEntry;
120	    }
121	  }
122	
123	  return existingComponents;
124	}
