126	/**
127	 * Generates a manifest of docs entries. This extends the existing manifest system to include docs
128	 * entries.
129	 *
130	 * - Unattached MDX entries (with 'unattached-mdx' tag) are added to a separate `docs` manifest.
131	 * - Attached MDX entries (with 'attached-mdx' tag) are added to their corresponding component
132	 *   manifests under a `docs` property.
133	 * - Docs entries without either tag are ignored.
134	 */
135	export const manifests: PresetPropertyFn<
136	  'experimental_manifests',
137	  StorybookConfigRaw,
138	  { manifestEntries: IndexEntry[] }
139	> = async (existingManifests = {}, { manifestEntries }) => {
140	  const startPerformance = performance.now();
141	
142	  const docsEntries = manifestEntries.filter(
143	    (entry): entry is DocsIndexEntry => entry.type === 'docs'
144	  );
145	
146	  if (docsEntries.length === 0) {
147	    return existingManifests;
148	  }
149	
150	  const { attachedEntries = [], unattachedEntries = [] } = groupBy(docsEntries, (entry) => {
151	    switch (true) {
152	      case entry.tags?.includes(Tag.UNATTACHED_MDX):
153	        return 'unattachedEntries';
154	      case entry.tags?.includes(Tag.ATTACHED_MDX):
155	        return 'attachedEntries';
156	      default:
157	        return 'ignored';
158	    }
159	  });
160	
161	  if (unattachedEntries.length === 0 && attachedEntries.length === 0) {
162	    return existingManifests;
163	  }
164	
165	  const existingManifestsWithDocs = existingManifests as ManifestsWithDocs;
166	
167	  const [unattachedDocs, updatedComponents] = await Promise.all([
168	    extractUnattachedDocsEntries(unattachedEntries),
169	    extractAttachedDocsEntries(attachedEntries, existingManifestsWithDocs.components),
170	  ]);
171	
172	  const processedCount = unattachedEntries.length + attachedEntries.length;
173	  logger.verbose(
174	    `Docs manifest generation took ${performance.now() - startPerformance}ms for ${processedCount} entries (${unattachedEntries.length} unattached, ${attachedEntries.length} attached)`
175	  );
176	
177	  const result = { ...existingManifestsWithDocs };
178	
179	  // Add unattached docs to the docs manifest
180	  if (Object.keys(unattachedDocs).length > 0) {
181	    result.docs = {
182	      v: 0,
183	      docs: unattachedDocs,
184	    };
185	  }
186	
187	  // Update the components manifest with attached docs
188	  if (updatedComponents) {
189	    result.components = updatedComponents;
190	  }
191	
192	  return result;
193	};
